];
const upgrades=[
 {icon:'🩸',name:'Bloodletting',rarity:'OCCULT RITE',text:'Weapon damage increased by 25%.',apply:()=>damage=Math.round(damage*1.25)},
 {icon:'🕯️',name:'Fleet of Foot',rarity:'ANCIENT BLESSING',text:'Move 15% faster and evade the grasping dead.',apply:()=>speed*=1.15},
 {icon:'🛡️',name:'Iron Covenant',rarity:'ANCIENT BLESSING',text:'Gain 1 armor and restore 20 vitality.',apply:()=>{armor++;hp=Math.min(maxHp,hp+20)}},
 {icon:'🦴',name:'Marrow Harvest',rarity:'OCCULT RITE',text:'Draw experience and treasure from farther away.',apply:()=>magnet+=55},
 {icon:'⚡',name:'Quickened Hex',rarity:'OCCULT RITE',text:'Attack 18% faster.',apply:()=>attackRate*=.82},
 {icon:'☠️',name:'Grave Appetite',rarity:'OCCULT RITE',text:'Deal 10% more damage and gain 8% critical chance.',apply:()=>{damage=Math.ceil(damage*1.1);crit+=8}},
 {icon:'💚',name:'Last Breath',rarity:'ANCIENT BLESSING',text:'Increase maximum vitality by 25 and heal fully.',apply:()=>{maxHp+=25;hp=maxHp}},
 {icon:'🌀',name:'Cinderstep',rarity:'ANCIENT BLESSING',text:'Dash recharges faster and travel farther.',apply:()=>{player.dashCd=Math.max(0,player.dashCd-1);speed+=5}}
];
function resize(){dpr=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;canvas.width=Math.floor(W*dpr);canvas.height=Math.floor(H*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);}
addEventListener('resize',resize);resize();
function formatTime(n){const m=Math.floor(n/60),s=Math.floor(n%60);return String(m).padStart(2,'0')+':'+String(s).padStart(2,'0')}
function showToast(text){const t=$('toast');t.textContent=text;t.classList.add('show');toastClock=2.2}
function updateUI(){
 $('timer').textContent=formatTime(elapsed);$('level').textContent=level;$('xpText').textContent=`${xp} / ${xpNeed}`;$('xpBar').style.width=`${xp/xpNeed*100}%`;$('hpText').textContent=`${Math.ceil(hp)} / ${maxHp}`;$('hpBar').style.width=`${hp/maxHp*100}%`;$('might').textContent=might;$('armor').textContent=armor;$('crit').textContent=crit+'%';$('fortune').textContent=fortune;$('damage').textContent=damage;$('kills').textContent=kills;
 $('wave').textContent=`NIGHT ${Math.floor(elapsed/90)+1} · ${elapsed<90?'THE HOLLOW COURT':elapsed<180?'THE SUNKEN CHAPEL':'THE BONE GARDEN'}`;$('waveProgress').style.width=((elapsed%90)/90*100)+'%';$('bagCount').textContent=`${bag.length} / 6`;
 $('weaponSlot').querySelector('.equip-icon').textContent=weapon.icon;$('weaponSlot').querySelector('.equip-name').textContent=weapon.name;$('weaponSlot').style.borderColor=rarityColors[weapon.rarity]||'#443e34';
 $('relicSlot').querySelector('.equip-icon').textContent=relic?relic.icon:'◈';$('relicSlot').querySelector('.equip-name').textContent=relic?relic.name:'Empty';$('relicSlot').style.borderColor=relic?rarityColors[relic.rarity]:'#443e34';
 $('slots').innerHTML='';for(let i=0;i<6;i++){const it=bag[i],el=document.createElement('button');el.className='slot '+(it?it.rarity+'':'empty');el.title=it?`${it.name} — ${it.desc}. Click to equip.`:'Empty';el.setAttribute('aria-label',el.title);if(it){el.innerHTML=`${it.icon}<span class="level">${it.rarity==='epic'?'IV':it.rarity==='rare'?'III':it.rarity==='magic'?'II':'I'}</span>`;el.onclick=()=>equipItem(i)}else el.innerHTML='';$('slots').appendChild(el)}
}
function addXp(n){xp+=n;while(xp>=xpNeed){xp-=xpNeed;level++;xpNeed=Math.round(xpNeed*1.28+3);openLevel()}updateUI()}
function openLevel(){paused=true;$('levelChoice').textContent=level;$('levelScreen').classList.remove('hidden');const options=[...upgrades].sort(()=>Math.random()-.5).slice(0,3);$('choices').innerHTML='';options.forEach(u=>{const b=document.createElement('button');b.className='choice';b.innerHTML=`<div class="icon">${u.icon}</div><div class="rarity-tag">${u.rarity}</div><h3>${u.name}</h3><p>${u.text}</p>`;b.onclick=()=>{u.apply();$('levelScreen').classList.add('hidden');paused=false;showToast(`${u.name.toUpperCase()} · BOON ACQUIRED`);updateUI()};$('choices').appendChild(b)})}
function applyItem(it){if(it.stat==='damage')damage+=it.value;if(it.stat==='crit')crit+=it.value;if(it.stat==='fortune')fortune+=it.value;if(it.stat==='speed')speed+=it.value;if(it.stat==='armor')armor+=it.value;if(it.stat==='health'){maxHp+=it.value;hp+=it.value}if(it.stat==='rate')attackRate=Math.max(.22,attackRate*(1-it.value))}
function unapplyItem(it){if(it.stat==='damage')damage-=it.value;if(it.stat==='crit')crit-=it.value;if(it.stat==='fortune')fortune-=it.value;if(it.stat==='speed')speed-=it.value;if(it.stat==='armor')armor-=it.value;if(it.stat==='health'){maxHp-=it.value;hp=Math.min(hp,maxHp)}if(it.stat==='rate')attackRate/=(1-it.value)}
function equipItem(i){const it=bag[i];if(!it)return;let old=it.type==='weapon'?weapon:relic;if(old&&old.name!=='Rustfang'&&bag.length>=6){showToast('SATCHEL FULL · MAKE ROOM FIRST');return}if(old&&old.name!=='Rustfang'){bag[i]=old}else{bag.splice(i,1)}if(old)unapplyItem(old);if(it.type==='weapon')weapon=it;else relic=it;applyItem(it);showToast(`${it.name.toUpperCase()} · EQUIPPED`);updateUI()}
function spawnEnemy(){const a=rand(0,Math.PI*2),dist=Math.max(W,H)*.62+rand(40,170),x=player.x+Math.cos(a)*dist,y=player.y+Math.sin(a)*dist;let type=Math.random()<.66?'ghoul':Math.random()<.78?'wraith':'brute';if(elapsed>80&&Math.random()<.12)type='brute';const def={ghoul:[20,43,12,9,'#8e9a6c'],wraith:[13,73,9,13,'#7f83bb'],brute:[76,27,17,20,'#a85e49']}[type];const scale=1+elapsed/180+curse*.12;enemies.push({x,y,type,hp:def[0]*scale,max:def[0]*scale,speed:def[1]*(1+elapsed/500),damage:def[2],r:def[3],color:def[4],hit:0,attack:rand(0,1.3),phase:rand(0,6.2),xp:type==='brute'?3:1});}
function spawnLoot(e){const template=pick(itemPool),r=Math.random(),rarity=r<.08+fortune*.001?'epic':r<.28+fortune*.002?'rare':r<.68?'magic':'common';const item={...template,rarity};if(e.type==='brute'||Math.random()<.1+fortune*.001){loot.push({x:e.x,y:e.y,item,life:70,bob:rand(0,6)});particlesBurst(e.x,e.y,'#e7b961',9)}else{gems.push({x:e.x,y:e.y,value:e.xp,color:e.type==='wraith'?'#9c91df':'#8bcf9d',r:4,mag:false})}}
function nearestTarget(){let best=null,bd=Infinity;for(const e of enemies){const d=Math.hypot(e.x-player.x,e.y-player.y);if(d<bd){bd=d;best=e}}return best}
function attack(){const e=nearestTarget();if(!e)return;let a=Math.atan2(e.y-player.y,e.x-player.x);player.angle=a;let isCrit=Math.random()<crit/100;projectiles.push({x:player.x+Math.cos(a)*18,y:player.y+Math.sin(a)*18,vx:Math.cos(a)*projectileSpeed,vy:Math.sin(a)*projectileSpeed,life:1.05,damage:damage*(isCrit?2:1),crit:isCrit,spin:rand(0,6)});particles.push({x:player.x+Math.cos(a)*18,y:player.y+Math.sin(a)*18,vx:Math.cos(a)*-30,vy:Math.sin(a)*-30,life:.17,color:'#eccb81',r:3})}
function particlesBurst(x,y,color,n=6){for(let i=0;i<n;i++){let a=rand(0,Math.PI*2),v=rand(25,120);particles.push({x,y,vx:Math.cos(a)*v,vy:Math.sin(a)*v,life:rand(.2,.6),color,r:rand(1,3)})}}
function dieEnemy(i){const e=enemies[i];kills++;if(Math.random()<.88)gems.push({x:e.x,y:e.y,value:e.xp,color:e.type==='wraith'?'#9c91df':'#8bcf9d',r:4,mag:false});if(Math.random()<.11+fortune*.003||e.type==='brute')spawnLoot(e);particlesBurst(e.x,e.y,e.color,e.type==='brute'?12:6);enemies.splice(i,1)}
function damagePlayer(amount){if(player.invuln>0)return;const actual=Math.max(1,amount-armor*1.6);hp-=actual;player.invuln=.55;shake=7;particlesBurst(player.x,player.y,'#df6455',7);updateUI();if(hp<=0)endRun()}
function pickLoot(){if(!nearestLoot)return;const {item}=nearestLoot;if(bag.length>=6){showToast('SATCHEL FULL · CLICK AN ITEM TO EQUIP');return}bag.push(item);loot.splice(loot.indexOf(nearestLoot),1);showToast(`${item.name.toUpperCase()} · ${item.rarity.toUpperCase()} FOUND`);nearestLoot=null;updateUI()}
function endRun(){run=false;paused=true;$('endTime').textContent=formatTime(elapsed);$('endKills').textContent=kills;$('endLevel').textContent=level;$('endCopy').textContent=`You survived ${formatTime(elapsed)} in the Hollow Court. The vault remembers the fallen.`;$('endScreen').classList.remove('hidden')}

