function endRun(){run=false;paused=true;$('endTime').textContent=formatTime(elapsed);$('endKills').textContent=kills;$('endLevel').textContent=level;$('endCopy').textContent=`You survived ${formatTime(elapsed)} in the Hollow Court. The vault remembers the fallen.`;$('endScreen').classList.remove('hidden')}
function hash(x,y){const n=Math.sin(x*127.1+y*311.7)*43758.5453;return n-Math.floor(n)}
function drawFloor(){const tile=64,left=Math.floor((player.x-W/2)/tile)-1,right=Math.ceil((player.x+W/2)/tile)+1,top=Math.floor((player.y-H/2)/tile)-1,bottom=Math.ceil((player.y+H/2)/tile)+1;ctx.fillStyle='#252522';ctx.fillRect(player.x-W/2,player.y-H/2,W,H);for(let tx=left;tx<=right;tx++)for(let ty=top;ty<=bottom;ty++){let h=hash(tx,ty),x=tx*tile,y=ty*tile;ctx.fillStyle=h>.78?'#292925':h<.12?'#22221f':'#262622';ctx.fillRect(x,y,tile-1,tile-1);ctx.strokeStyle='#33332e';ctx.lineWidth=1;ctx.strokeRect(x+.5,y+.5,tile-2,tile-2);if(h>.9){ctx.strokeStyle='#3b3931';ctx.beginPath();ctx.moveTo(x+14,y+11);ctx.lineTo(x+22,y+17);ctx.lineTo(x+19,y+27);ctx.stroke()}if(h<.035){ctx.fillStyle='#63583d';ctx.globalAlpha=.6;ctx.beginPath();ctx.arc(x+32,y+30,2,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1}}
// old crypt markings on a sparse world grid
for(let tx=left;tx<=right;tx++)for(let ty=top;ty<=bottom;ty++){const h=hash(tx+218,ty-31);if(h>.987){const x=tx*tile+32,y=ty*tile+32;ctx.save();ctx.translate(x,y);ctx.strokeStyle='#504638';ctx.globalAlpha=.42;ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,0,12,0,Math.PI*2);ctx.moveTo(-7,0);ctx.lineTo(7,0);ctx.moveTo(0,-7);ctx.lineTo(0,7);ctx.stroke();ctx.restore()}}
}
function drawEnemy(e){const bob=Math.sin(elapsed*5+e.phase)*1.5;ctx.save();ctx.translate(e.x,e.y+bob);const big=e.type==='boss';if(big){ctx.fillStyle='#d29c47';ctx.globalAlpha=.18;ctx.beginPath();ctx.arc(0,0,38+Math.sin(elapsed*4)*3,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1}
ctx.fillStyle='#0c0b0a88';ctx.beginPath();ctx.ellipse(0,e.r*.65,e.r*1.1,e.r*.55,0,0,Math.PI*2);ctx.fill();ctx.fillStyle=e.hit>0?'#fff0c8':e.color;ctx.strokeStyle='#211d19';ctx.lineWidth=3;
if(e.type==='wraith'){ctx.beginPath();ctx.moveTo(-e.r,-2);ctx.quadraticCurveTo(-e.r,-e.r*1.3,0,-e.r);ctx.quadraticCurveTo(e.r,-e.r*1.3,e.r,-2);ctx.lineTo(e.r*.7,e.r);ctx.lineTo(e.r*.2,e.r*.5);ctx.lineTo(-e.r*.2,e.r);ctx.lineTo(-e.r*.7,e.r*.4);ctx.closePath();ctx.fill();ctx.stroke();ctx.fillStyle='#d4c9f3';ctx.fillRect(-5,-4,3,2);ctx.fillRect(3,-4,3,2)}else if(big){ctx.beginPath();ctx.arc(0,0,e.r,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.fillStyle='#49372b';ctx.beginPath();ctx.moveTo(-18,-16);ctx.lineTo(-27,-32);ctx.lineTo(-8,-23);ctx.moveTo(18,-16);ctx.lineTo(27,-32);ctx.lineTo(8,-23);ctx.fill();ctx.fillStyle='#f9d277';ctx.fillRect(-9,-5,5,4);ctx.fillRect(5,-5,5,4)}else{ctx.beginPath();ctx.ellipse(0,3,e.r*.8,e.r,0,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.fillStyle='#baa87b';ctx.beginPath();ctx.arc(0,-e.r*.45,e.r*.5,0,Math.PI*2);ctx.fill();ctx.fillStyle='#efcf79';ctx.fillRect(-5,-e.r*.5,3,2);ctx.fillRect(3,-e.r*.5,3,2);if(e.type==='brute'){ctx.strokeStyle=e.color;ctx.lineWidth=5;ctx.beginPath();ctx.moveTo(-e.r*.6,2);ctx.lineTo(-e.r*1.3,10);ctx.moveTo(e.r*.6,2);ctx.lineTo(e.r*1.3,10);ctx.stroke()}}
if(e.hp<e.max||big){const bw=big?70:30,y=-e.r-10;ctx.fillStyle='#171310';ctx.fillRect(-bw/2,y,bw,4);ctx.fillStyle=big?'#d7aa58':'#c45449';ctx.fillRect(-bw/2,y,bw*clamp(e.hp/e.max,0,1),4);if(big){ctx.font='9px DM Mono';ctx.textAlign='center';ctx.fillStyle='#f1d8a4';ctx.fillText('BELLWARDEN',0,y-5)}}ctx.restore()}
function drawPlayer(){ctx.save();ctx.translate(player.x,player.y);ctx.rotate(player.angle);const flash=player.invuln>0&&Math.floor(elapsed*20)%2===0;ctx.fillStyle='#0a0909a8';ctx.beginPath();ctx.ellipse(0,8,17,11,0,0,Math.PI*2);ctx.fill();ctx.fillStyle=flash?'#fff0ca':'#27222a';ctx.strokeStyle='#b49b69';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(-12,10);ctx.lineTo(-10,-8);ctx.quadraticCurveTo(-7,-16,0,-17);ctx.quadraticCurveTo(10,-16,12,-7);ctx.lineTo(13,10);ctx.quadraticCurveTo(0,17,-12,10);ctx.fill();ctx.stroke();ctx.fillStyle='#cbb68b';ctx.beginPath();ctx.arc(0,-11,6.5,0,Math.PI*2);ctx.fill();ctx.fillStyle='#171519';ctx.beginPath();ctx.moveTo(-6,-14);ctx.lineTo(-7,-22);ctx.lineTo(0,-17);ctx.lineTo(8,-21);ctx.lineTo(6,-11);ctx.fill();ctx.fillStyle='#e6bd70';ctx.fillRect(2,-13,3,2);ctx.strokeStyle='#e4d6b7';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(8,0);ctx.lineTo(22,-2);ctx.stroke();ctx.strokeStyle='#a9824c';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(7,-3);ctx.lineTo(7,3);ctx.stroke();ctx.restore();}
function drawLoot(){nearestLoot=null;let best=42;for(const drop of loot){drop.bob+=.04;const d=Math.hypot(drop.x-player.x,drop.y-player.y);if(d<best){best=d;nearestLoot=drop}const c=rarityColors[drop.item.rarity]||'#fff';ctx.save();ctx.translate(drop.x,drop.y+Math.sin(drop.bob)*3);ctx.globalAlpha=.25;ctx.fillStyle=c;ctx.beginPath();ctx.arc(0,0,14,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;ctx.fillStyle='#171411';ctx.strokeStyle=c;ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(0,-10);ctx.lineTo(10,0);ctx.lineTo(0,10);ctx.lineTo(-10,0);ctx.closePath();ctx.fill();ctx.stroke();ctx.fillStyle=c;ctx.font='12px serif';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(drop.item.icon,0,0);ctx.restore()}$('lootPrompt').classList.toggle('show',!!nearestLoot)}
function draw(){ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,W,H);ctx.save();if(shake>0)ctx.translate(rand(-shake,shake),rand(-shake,shake));ctx.translate(W/2-player.x,H/2-player.y);drawFloor();for(const g of gems){ctx.save();ctx.translate(g.x,g.y);ctx.fillStyle=g.color;ctx.shadowColor=g.color;ctx.shadowBlur=12;ctx.beginPath();ctx.moveTo(0,-g.r);ctx.lineTo(g.r*.75,0);ctx.lineTo(0,g.r);ctx.lineTo(-g.r*.75,0);ctx.closePath();ctx.fill();ctx.restore()}for(const d of loot){/* drawn in front of creatures below */}for(const e of enemies)drawEnemy(e);drawLoot();for(const p of projectiles){ctx.save();ctx.translate(p.x,p.y);ctx.rotate(p.spin);ctx.fillStyle=p.crit?'#fff0aa':'#e5c27b';ctx.shadowColor='#efbd69';ctx.shadowBlur=12;ctx.beginPath();ctx.moveTo(9,0);ctx.lineTo(0,3);ctx.lineTo(-5,0);ctx.lineTo(0,-3);ctx.closePath();ctx.fill();ctx.restore()}for(const p of particles){ctx.globalAlpha=clamp(p.life*2,0,1);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1;drawPlayer();ctx.restore();if(shake>0)shake=Math.max(0,shake-.45)}

